const fs = require('fs');
const { Readable } = require('stream');
const zlib = require('zlib');

// .docx is a ZIP file; we'll parse it manually
const buf = fs.readFileSync('/workspace/testbed/docs/customer_report.docx');

// Find local file headers and extract word/document.xml
let offset = 0;
while (offset < buf.length - 4) {
  if (buf.readUInt32LE(offset) !== 0x04034b50) break; // local file header signature
  const compMethod = buf.readUInt16LE(offset + 8);
  const compSize = buf.readUInt32LE(offset + 18);
  const uncompSize = buf.readUInt32LE(offset + 22);
  const fnLen = buf.readUInt16LE(offset + 26);
  const exLen = buf.readUInt16LE(offset + 28);
  const fileName = buf.toString('utf8', offset + 30, offset + 30 + fnLen);
  const dataStart = offset + 30 + fnLen + exLen;
  const dataEnd = dataStart + compSize;

  if (fileName === 'word/document.xml') {
    let data;
    if (compMethod === 0) {
      data = buf.slice(dataStart, dataEnd);
    } else {
      data = zlib.inflateRawSync(buf.slice(dataStart, dataEnd));
    }
    // Strip XML tags and print text
    const xml = data.toString('utf8');
    // Extract text from <w:t> tags
    const texts = [];
    let currentPara = '';
    const parts = xml.split(/<\/?w:p[ >\/]/);
    for (const part of parts) {
      const matches = [...part.matchAll(/<w:t[^>]*>([^<]*)<\/w:t>/g)];
      if (matches.length > 0) {
        texts.push(matches.map(m => m[1]).join(''));
      } else if (texts.length > 0 && texts[texts.length-1] !== '') {
        texts.push('');
      }
    }
    console.log(texts.filter((t,i) => !(t === '' && texts[i-1] === '')).join('\n'));
    break;
  }
  offset = dataEnd;
}
"
